#!/usr/bin/env bash
# Creates one PostgreSQL database per CONSOLIDATED microservice (7) and loads, in order:
#   1. NN_<service>.sql          - the consolidated data model (generated by tools/gen_database_v2.py)
#   2. seed/NN_<service>.seed.sql - minimal reference data so the workflow can run
# Order: identity first, then revenue & finance and operations & supply, then the rest.
# Safe to re-run: a database whose data model is already applied is skipped.
#
#   PGHOST=localhost PGUSER=postgres PGPASSWORD=... ./deploy.sh
#   DB_PREFIX=v2test_ ./deploy.sh      # other database names, e.g. v2test_identity_org (default prefix: new_hims_)
set -euo pipefail
cd "$(dirname "$0")"
export PGHOST="${PGHOST:-localhost}" PGPORT="${PGPORT:-5432}" PGUSER="${PGUSER:-hims}"
DB_PREFIX="${DB_PREFIX:-new_hims_}"
ORDER="01_identity_org 05_revenue_finance 06_operations_supply 02_patient_engagement 03_clinical_care 04_diagnostics 07_integration_comms"
for name in $ORDER; do
  db="${DB_PREFIX}${name#*_}"
  if ! psql -d postgres -Atqc "select 1 from pg_database where datname='$db'" | grep -q 1; then
    createdb -E UTF8 -T template0 "$db"; echo "created database $db"
  fi
  if [ "$(psql -d "$db" -Atqc "select to_regclass('evt.outbox') is not null" | tr -d '\r')" = "t" ]; then
    echo "[$db] data model already applied - skipping ${name}.sql"
  else
    echo "[$db] applying ${name}.sql"; psql -v ON_ERROR_STOP=1 -q -d "$db" -f "${name}.sql"
  fi
  [ -f "seed/${name}.seed.sql" ] && { echo "[$db] applying seed"; psql -v ON_ERROR_STOP=1 -q -d "$db" -f "seed/${name}.seed.sql" >/dev/null; }
done
echo "done."
